import assert from 'node:assert/strict';
import {readExactJSON,MAX_BYTES} from './json-import.mjs';

// Synthetic inputs only. Compare reported file size with independently generated bytes.
const record={sourceId:'000123',date:'2026-10-25',claim:'Synthetic résumé — café',status:'reported',kind:'source',group:''};
const raw=JSON.stringify({schema:'evidence-timeline-v1',records:[record]});
const bytes=Buffer.from(raw,'utf8');
const fake=(size=bytes.length,body=bytes,name='synthetic.json')=>({
  name,size,arrayBuffer:async()=>Uint8Array.from(body).buffer
});
let checks=0;
const valid=await readExactJSON(new File([bytes],'synthetic.json',{type:'application/json'}));
assert.equal(valid[0].sourceId,'000123');checks++;
assert.equal(valid[0].claim,record.claim);checks++;
assert.deepEqual(await readExactJSON(fake(bytes.length,bytes,'SYNTHETIC.JSON')),valid);checks++;
for(const size of [0,bytes.length-1,bytes.length+1,-1,1.5,NaN,undefined,Infinity]){
  await assert.rejects(readExactJSON(fake(size)),/file size|does not match/i);
  checks++;
}
await assert.rejects(readExactJSON(fake(MAX_BYTES+1)),/exceeds/i);checks++;
await assert.rejects(readExactJSON(fake(0,Buffer.alloc(MAX_BYTES+1))),/exceeds/i);checks++;
await assert.rejects(readExactJSON(fake(bytes.length,bytes,'synthetic.csv')),/Choose a JSON export/);checks++;
await assert.rejects(readExactJSON({...fake(),arrayBuffer:async()=>new Uint8Array(bytes)}),/Invalid file content/);checks++;
await assert.rejects(readExactJSON(fake(bytes.length,Buffer.from(raw.slice(0,-1),'utf8'))),/does not match/i);checks++;
await assert.rejects(readExactJSON(fake(2,Buffer.from([0xc3,0x28]))),/Invalid UTF-8/);checks++;
await assert.rejects(readExactJSON(fake(3,Buffer.from([123,0,125]))),/NUL byte/);checks++;
const wrong=Buffer.from(JSON.stringify({schema:'wrong',records:[record]}),'utf8');
await assert.rejects(readExactJSON(fake(wrong.length,wrong)),/schema/);checks++;
const dup=Buffer.from(JSON.stringify({schema:'evidence-timeline-v1',records:[record,record]}),'utf8');
await assert.rejects(readExactJSON(fake(dup.length,dup)),/duplicate source ID/);checks++;
// A deceptive metadata object must not bypass the actual byte count.
await assert.rejects(readExactJSON({...fake(),size:bytes.length+2,text:async()=>raw}),/does not match/i);checks++;
console.log('PASS: '+checks+' FT-05 exact JSON file-byte integrity and schema assertions');
